@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-4">
    <div class="card-header">
        <h5 class="mb-0">
            @WarehouseState.CurrentWarehouse.Name — Inventory Alerts
        </h5>
    </div>
    <div class="card-body">
        <p class="display-4 text-center">
            <span class="badge bg-warning text-dark">@AlertService.CurrentAlertCount</span>
        </p>
        <p class="text-center text-muted">
            Items currently below minimum stock level.
            <br />
            <small>Auto-refreshes every 10 seconds.</small>
        </p>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling while this page is visible
        AlertService.Subscribe();
    }

    public void Dispose()
    {
        // Stop polling when user leaves this page
        AlertService.Unsubscribe();

        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

